void cmd_trace( Cmd cmd  )
{  
    #if DBG_CMD == 1
#if	defined PLATFORM_CM800 || defined PLATFORM_933		//def PLATFORM_CM800
    {
        TRACE_CMD("[CMD_%04d]",(cmd & (INPUT_ON - 1)) );
	
	    if( cmd & INPUT_ON         ) TRACE_CMD("--ON\n\r" );
	    else
	    if( cmd & INPUT_RF_EXT     ) TRACE_CMD("--EXT\n\r" );
	    else
	    if( cmd & INPUT_RF_RELEASE ) TRACE_CMD("--RELEASE\n\r" );
	    else
	    TRACE_CMD("\n\r" );
		}
#else
    {
       dbg_tx_text("[CMD_");
       dbg_tx_u((cmd & (INPUT_ON - 1)), 4);
       dbg_tx_text("]");
       if( cmd & INPUT_ON         ) dbg_tx_text("--ON\n\r" );
       else
       if( cmd & INPUT_RF_EXT     ) dbg_tx_text("--EXT\n\r" );
       else
       if( cmd & INPUT_RF_RELEASE ) dbg_tx_text("--RELEASE\n\r" );
       else
          dbg_tx_text("\n\r" );
    }
#endif
    #endif
}

